import Foundation
@inline(never) func old(_ ids: [String]) -> [String] {
    var unique: [String] = []
    for id in ids where !unique.contains(id) { unique.append(id) }
    return unique
}
@inline(never) func candidate(_ ids: [String]) -> [String] {
        guard ids.count > 1 else { return ids }
        var unique: [String] = []
        for (index, id) in ids.enumerated() where !unique.contains(id) {
            unique.append(id)
            // Linear lookup wins for the usual small selection. Switch once there
            // are enough distinct ids and remaining lookups to amortize hashing.
            if unique.count == 64 && ids.count - index > 32 {
                var seen = Set(unique)
                for remaining in ids[(index + 1)...] where seen.insert(remaining).inserted {
                    unique.append(remaining)
                }
                break
            }
        }
        return unique
    }
struct Row: Codable { let size: Int; let cardinality: Int; let oldNs: Double; let candidateNs: Double }

var rows: [Row] = []
let dates: [Date] = [Date(timeIntervalSince1970: 0), Date(timeIntervalSince1970: 1770001234.567)]
var sum = 0
for n in [1, 4, 16, 32, 64, 256, 1024] {
 for cardinality in Set([1, max(1, n / 2), n]).sorted() {
    let strings = (0..<cardinality).map { i in
        String(repeating: String(format: "%016llx", UInt64(i+1) &* 11400714819323198485), count: 4)
    }
    let ids=(0..<n).map {strings[$0 % cardinality]}
    guard old(ids) == candidate(ids) else { fatalError("unexpected change") }
    let count=max(1,min(4000,180000/(n*max(4,cardinality))))
    func time(_ f: ([String]) -> [String]) -> Double {
        let start=DispatchTime.now().uptimeNanoseconds
        for _ in 0..<count { sum &+= f(ids).count }
        return Double(DispatchTime.now().uptimeNanoseconds-start)/Double(count)
    }
    var times=[[Double](),[Double]()]
    for round in 0..<9 {for lane in round.isMultiple(of:2) ? [0,1] : [1,0] {
        times[lane].append(time(lane==0 ? old : candidate))
    }}
    rows.append(Row(size:n,cardinality:cardinality,oldNs:times[0].sorted()[4],candidateNs:times[1].sorted()[4]))
 }
}
let once = ISO8601DateFormatter()
guard dates.allSatisfy({once.string(from: $0)==ISO8601DateFormatter().string(from: $0)}) else {fatalError("timestamp differs")}
var stampTimes=[[Double](),[Double]()]
for round in 0..<9 { for lane in round.isMultiple(of:2) ? [0,1] : [1,0] {
   let start=DispatchTime.now().uptimeNanoseconds
   for i in 0..<100 { sum &+= (lane==0 ? ISO8601DateFormatter() : once).string(from:dates[i % dates.count]).utf8.count }
   stampTimes[lane].append(Double(DispatchTime.now().uptimeNanoseconds-start)/100.0)
}}
struct DataSet: Codable { let ids: [Row]; let timestampOldNs: Double; let timestampRetainedNs: Double; let checksum: Int }
let result = DataSet(ids: rows, timestampOldNs: stampTimes[0].sorted()[4], timestampRetainedNs: stampTimes[1].sorted()[4], checksum: sum)
print(String(decoding:try JSONEncoder().encode(result),as:UTF8.self))
FileHandle.standardError.write(Data("checksum \\(sum)\n".utf8))
